solution.solution.js:
function wordFrequencies(text) {
  const counts = new Map();
  for (const word of text.toLowerCase().match(/[a-z']+/g) ?? []) {
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }
  return counts;
}

function topWords(text, n) {
  return [...wordFrequencies(text)].sort((a, b) => b[1] - a[1]).slice(0, n);
}

function saveState(state) {
  return JSON.stringify({
    tags: [...state.tags],
    scores: Object.fromEntries(state.scores),
    name: state.name,
  });
}

function loadState(text) {
  const data = JSON.parse(text);
  return {
    tags: new Set(data.tags),
    scores: new Map(Object.entries(data.scores)),
    name: data.name,
  };
}

unitTests:
test("counting words", () => {
  const counts = wordFrequencies("The cat and the hat. THE end!");
  checkEq([...counts], [["the", 3], ["cat", 1], ["and", 1], ["hat", 1], ["end", 1]]);
  checkEq(wordFrequencies("").size, 0);
  checkEq(wordFrequencies("don't stop, don't").get("don't"), 2);
});

test("top words with stable ties", () => {
  checkEq(topWords("b a b c a b", 2), [["b", 3], ["a", 2]]);
  checkEq(topWords("x y z", 2), [["x", 1], ["y", 1]]);
  checkEq(topWords("", 3), []);
});

test("JSON round trip keeps Maps and Sets", () => {
  const state = { tags: new Set(["js", "web"]), scores: new Map([["ada", 3], ["bob", 5]]), name: "demo" };
  const text = saveState(state);
  checkEq(typeof text, "string");
  checkEq(JSON.parse(text).tags, ["js", "web"]);
  const back = loadState(text);
  check(back.tags instanceof Set, "tags should be a Set");
  check(back.scores instanceof Map, "scores should be a Map");
  checkEq([...back.tags], ["js", "web"]);
  checkEq(back.scores.get("bob"), 5);
  checkEq(back.name, "demo");
});

